function readQuestion(query) {
  const question = query?.["Research Question"];
  const valid = typeof question === "string" && Boolean(question.trim()) && question.length <= 1500;
  return { valid, question: valid ? question : "" };
}
return [{ json: readQuestion($input.first().json.query) }];

return [
  {
    json: {
      status: 400,
